.cocreatesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2438;
    background: linear-gradient(160deg, #f6f2ee 0%, #efe7e0 100%);
    border-radius: 18px;
}

.cocreatesim-container * {
    box-sizing: border-box;
}

.cocreatesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2b1f3f 0%, #4a2e54 55%, #7a3b54 100%);
    color: #f7f1ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(43, 31, 63, 0.32);
}

.cocreatesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cocreatesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0cf9a;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.cocreatesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #efe2e6;
}

.cocreatesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a2e54;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cocreatesim-period-counter #currentDay,
.cocreatesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2b1f3f;
}

.cocreatesim-round-name {
    background: #e7d8e2;
    color: #4a2e54;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cocreatesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3520;
    background: #fae3da;
    padding: 4px 12px;
    border-radius: 999px;
}

.cocreatesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cocreatesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7ddd4;
    box-shadow: 0 4px 14px rgba(43, 31, 63, 0.06);
    border-top: 4px solid #7a3b54;
}

.cocreatesim-card-impact { border-top-color: #6a2d8f; }
.cocreatesim-card-align { border-top-color: #2f6fb0; }
.cocreatesim-card-cocreate { border-top-color: #138a6e; }
.cocreatesim-card-margin { border-top-color: #c08a16; }

.cocreatesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a72;
}

.cocreatesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b1f3f;
}

.cocreatesim-card-impact .cocreatesim-value { color: #6a2d8f; }
.cocreatesim-card-align .cocreatesim-value { color: #2f6fb0; }
.cocreatesim-card-cocreate .cocreatesim-value { color: #138a6e; }
.cocreatesim-card-margin .cocreatesim-value { color: #b07e10; }

.cocreatesim-sublabel {
    font-size: 0.76rem;
    color: #98867d;
    line-height: 1.35;
}

.cocreatesim-margin-fail .cocreatesim-value { color: #c0392b; }
.cocreatesim-margin-fail { border-top-color: #c0392b; }
.cocreatesim-margin-ok .cocreatesim-value { color: #138a6e; }

.cocreatesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2b1f3f;
    color: #f3ebf0;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cocreatesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0cf9a;
}

.cocreatesim-budget-over #budgetDisplay {
    color: #ff9d8a;
}

.cocreatesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #7a3b54;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(43, 31, 63, 0.05);
}

.cocreatesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cocreatesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #4a2e54;
    margin-bottom: 6px;
}

.cocreatesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #423a4d;
}

.cocreatesim-briefing-text strong { color: #138a6e; }
.cocreatesim-briefing-text em { color: #9a3520; font-style: italic; }

.cocreatesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7ddd4;
    box-shadow: 0 4px 14px rgba(43, 31, 63, 0.06);
}

.cocreatesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #4a2e54;
    border-bottom: 2px solid #efe7e0;
    padding-bottom: 8px;
}

.cocreatesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3b2f47;
    margin: 14px 0 6px;
}

.cocreatesim-container select,
.cocreatesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c8d2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf7f4;
    color: #2a2438;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cocreatesim-container select:focus,
.cocreatesim-container input[type="number"]:focus {
    outline: none;
    border-color: #7a3b54;
    box-shadow: 0 0 0 3px rgba(122, 59, 84, 0.15);
}

.cocreatesim-container select option {
    background-color: #ffffff;
    color: #2a2438;
}

.cocreatesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7a3b54;
}

.cocreatesim-range-readout,
.cocreatesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6a2d8f;
    margin-top: 4px;
}

.cocreatesim-range-readout span:last-child,
.cocreatesim-alloc-readout span:nth-child(2) {
    color: #138a6e;
    font-weight: 800;
}

.cocreatesim-hint {
    font-size: 0.8rem;
    color: #98867d;
    margin-top: 4px;
    line-height: 1.4;
}

.cocreatesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cocreatesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f8f3f6;
    border: 1px solid #ebe0e7;
    border-radius: 9px;
    padding: 8px 12px;
}

.cocreatesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3b2f47;
}

.cocreatesim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.cocreatesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cocreatesim-container .btn-primary {
    background: linear-gradient(135deg, #6a2d8f 0%, #7a3b54 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(106, 45, 143, 0.28);
}

.cocreatesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.cocreatesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c8d2;
    color: #8a7a72;
}

.cocreatesim-coach {
    background: #2b1f3f;
    color: #f3ebf0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 31, 63, 0.24);
}

.cocreatesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d6a9c8;
    margin-bottom: 8px;
}

.cocreatesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cocreatesim-coach-body strong { color: #f0cf9a; }
.cocreatesim-coach-body em { color: #ffb59f; font-style: italic; }

.cocreatesim-history,
.cocreatesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7ddd4;
    box-shadow: 0 4px 14px rgba(43, 31, 63, 0.06);
}

.cocreatesim-history h3,
.cocreatesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #4a2e54;
}

.cocreatesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3b2f47;
}

.cocreatesim-container table#usfHistoryTable th {
    background: #f2e9ef;
    color: #4a2e54;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3d3df;
}

.cocreatesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1e8ee;
}

.cocreatesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6f9;
}

.cocreatesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cocreatesim-container {
        padding: 14px;
    }
    .cocreatesim-header h1 {
        font-size: 1.7rem;
    }
    .cocreatesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cocreatesim-value {
        font-size: 2rem;
    }
    .cocreatesim-clock {
        margin-left: 0;
    }
    .cocreatesim-period-counter {
        font-size: 0.88rem;
    }
    .cocreatesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cocreatesim-alloc-row {
        flex-wrap: wrap;
    }
    .cocreatesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .cocreatesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

