.cocreate-cm{background:#ffffff;border:1px solid #e7ddd6;border-radius:12px;padding:22px 24px;margin:18px 0;color:#2b2019;font-family:inherit;box-shadow:0 2px 10px rgba(44,30,20,0.06);}
