(function() {
    'use strict';

    class CoCreateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Co-Creating Change`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Atelier Cadence / Veridian Mobilité).
            this.START_IMPACT = 12;       // behaviour/business-outcome change is near zero today
            this.START_ALIGN = 20;        // three sponsors pull apart at kickoff
            this.START_COCREATE = 10;     // nothing co-created yet
            this.START_MARGIN = 28;       // average custom-programme contribution margin %
            this.MARGIN_HURDLE = 22;      // internal approval gate
            this.BUDGET_CAP = 840;        // EUR 840k hard cap, in thousands
            this.TARGET_IMPACT = 60;      // a credible transformation outcome
            this.WIN_COMPOSITE = 70;      // top performance-tier gate (reachable, see trace)

            // Concept truths.
            this.TRUE_NEED = `transform`;
            this.TRUE_METRIC = `behaviour`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    impact: this.START_IMPACT,
                    align: this.START_ALIGN,
                    cocreate: this.START_COCREATE,
                    margin: this.START_MARGIN,
                    budgetUsed: 0,
                    overran: false,
                    prevOverBy: 0,
                    lostMandate: false,
                    impactHistory: [this.START_IMPACT],
                    alignHistory: [this.START_ALIGN],
                    cocreateHistory: [this.START_COCREATE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a MIDDLING / neutral mix, NOT the textbook-correct play.
                state.decisions = {
                    need: `train`,
                    metric: `completion`,
                    candour: 50,
                    cocreate: `advisory`,
                    onjob: 200,
                    coaching: 160,
                    classroom: 320,
                    digital: 160,
                    scorecard: `cfo`,
                    scope: `ignore`,
                    speed: 50,
                    segment: `uniform`,
                    measure: `endcourse`,
                    renewal: `referral`,
                    derisk: `senior`,
                    pitch: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const need = document.getElementById(`needInput`);
                const metric = document.getElementById(`metricInput`);
                const cand = document.getElementById(`candourInput`);
                if (need) decisions.need = need.value;
                if (metric) decisions.metric = metric.value;
                if (cand) decisions.candour = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.candour) || decisions.candour < 0 || decisions.candour > 100) {
                    warn(`warn_candour_range`); return false;
                }
            } else if (round === 2) {
                const co = document.getElementById(`cocreateInput`);
                if (co) decisions.cocreate = co.value;
                const onjob = document.getElementById(`onjobInput`);
                const coaching = document.getElementById(`coachingInput`);
                const classroom = document.getElementById(`classInput`);
                const digital = document.getElementById(`digitalInput`);
                if (onjob) decisions.onjob = parseFloat(onjob.value);
                if (coaching) decisions.coaching = parseFloat(coaching.value);
                if (classroom) decisions.classroom = parseFloat(classroom.value);
                if (digital) decisions.digital = parseFloat(digital.value);
                const parts = [decisions.onjob, decisions.coaching, decisions.classroom, decisions.digital];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.onjob + decisions.coaching + decisions.classroom + decisions.digital);
                if (total !== this.BUDGET_CAP) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const sc = document.getElementById(`scorecardInput`);
                const sp = document.getElementById(`scopeInput`);
                const spd = document.getElementById(`speedInput`);
                const seg = document.getElementById(`segmentInput`);
                if (sc) decisions.scorecard = sc.value;
                if (sp) decisions.scope = sp.value;
                if (spd) decisions.speed = parseInt(spd.value, 10);
                if (seg) decisions.segment = seg.value;
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const re = document.getElementById(`renewalInput`);
                const de = document.getElementById(`deriskInput`);
                const pi = document.getElementById(`pitchInput`);
                if (me) decisions.measure = me.value;
                if (re) decisions.renewal = re.value;
                if (de) decisions.derisk = de.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // impact = behaviour/business-outcome change (CHRO + COO buy this).
            // align  = how balanced across the three sponsors.
            // cocreate = how much Veridian's own people are in design & delivery.
            // marginDelta = change to contribution margin %.
            // spend = extra euro committed beyond the R2 allocation (can breach the cap).
            let impactDelta = 0, alignDelta = 0, cocreateDelta = 0, marginDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the REAL need, not the stated request (Common Error 1: order-taking).
                if (d.need === this.TRUE_NEED) {
                    impactDelta += 15; alignDelta += 6; coachKey = `coach_r1_need_right`;
                } else if (d.need === `upskill`) {
                    impactDelta += 2; coachKey = `coach_r1_upskill`;
                } else if (d.need === `comms`) {
                    impactDelta -= 4; coachKey = `coach_r1_comms`;
                } else {
                    impactDelta -= 8; alignDelta -= 4; coachKey = `coach_r1_train`;
                }

                // Headline metric: the business outcome the CHRO/COO buy. Single-sponsor metrics
                // (completion = CFO, satisfaction = smile-sheet) under-serve two of three sponsors.
                if (d.metric === this.TRUE_METRIC) {
                    impactDelta += 12; alignDelta += 10;
                    if (d.need === this.TRUE_NEED) coachKey = `coach_r1_diag_sharp`;
                } else if (d.metric === `completion`) {
                    alignDelta -= 6; impactDelta -= 4; coachKey = `coach_r1_completion`;
                } else if (d.metric === `satisfaction`) {
                    impactDelta -= 8; alignDelta -= 4; coachKey = `coach_r1_satisfaction`;
                } else {
                    impactDelta -= 6; alignDelta -= 6; coachKey = `coach_r1_attendance`;
                }

                // Candour: willingness to name the legacy-P&L political barrier.
                if (d.candour >= 60) { impactDelta += 7; }
                else if (d.candour <= 25) { impactDelta -= 7; coachKey = `coach_r1_lowcandour`; }

                summaryKey = (d.need === this.TRUE_NEED && d.metric === this.TRUE_METRIC) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Co-design the architecture: co-creation mechanism + 70-20-10 format mix.
                // Co-creation is the VALUE PROPOSITION (Common Error 2: designing for, not with).
                switch (d.cocreate) {
                    case `codesign`: cocreateDelta += 30; impactDelta += 10; alignDelta += 4; coachKey = `coach_r2_codesign`; break;
                    case `advisory`: cocreateDelta += 10; impactDelta += 2; coachKey = `coach_r2_advisory`; break;
                    case `inhouse`: cocreateDelta -= 6; impactDelta -= 6; alignDelta -= 4; coachKey = `coach_r2_inhouse`; break;
                }

                // 70-20-10: on-the-job (70) drives behaviour change; coaching (20) supports it;
                // classroom (10) is formal instruction — satisfaction-heavy, behaviour-light.
                // Margin is shaped by efficiency: classroom-heavy faculty time erodes margin;
                // a balanced application-led mix protects it. Total is fixed at the cap by validation.
                const onjob = d.onjob, coaching = d.coaching, classroom = d.classroom, digital = d.digital;
                const cap = this.BUDGET_CAP;
                const applied = onjob + coaching;                 // the "70 + 20"
                const formal = classroom;                          // the "10"
                const appliedShare = applied / cap;               // target ~0.5+ for 70-20-10
                const classShare = classroom / cap;

                if (appliedShare >= 0.55 && classShare <= 0.30 && onjob >= coaching) {
                    impactDelta += 18; coachKey = (d.cocreate === `codesign`) ? `coach_r2_balanced` : coachKey;
                    marginDelta += 1;
                } else if (classShare >= 0.55) {
                    // Classroom-only intensives: high satisfaction, low behaviour change — the €1.6M trap.
                    impactDelta -= 10; marginDelta -= 3; coachKey = `coach_r2_classheavy`;
                } else if (appliedShare >= 0.40) {
                    impactDelta += 8;
                } else {
                    impactDelta += 2;
                }

                // Over-reliance on cheap digital self-paced buys completion, not conviction.
                if (digital / cap >= 0.45) { impactDelta -= 6; marginDelta += 2; coachKey = `coach_r2_digitalheavy`; }
                // Starving the formal "10" entirely under-supports the applied work.
                if (formal <= 40) { impactDelta -= 4; }

                summaryKey = (appliedShare >= 0.55 && classShare <= 0.30 && d.cocreate === `codesign`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Reconcile sponsor KPIs + defend scope against the cheaper bid (Common Error 3).
                switch (d.scorecard) {
                    case `balanced`: alignDelta += 26; impactDelta += 6; coachKey = `coach_r3_balanced`; break;
                    case `cfo`: alignDelta -= 10; impactDelta -= 8; marginDelta += 2; coachKey = `coach_r3_cfo`; break;
                    case `chro`: alignDelta -= 8; impactDelta += 4; marginDelta -= 3; coachKey = `coach_r3_chro`; break;
                    case `defer`: alignDelta -= 12; impactDelta -= 4; coachKey = `coach_r3_defer`; break;
                }

                // Defending the co-creation premium vs matching/ignoring the consultancy bid.
                switch (d.scope) {
                    case `premium`: alignDelta += 8; cocreateDelta += 8; coachKey = (d.scorecard === `balanced`) ? `coach_r3_premium` : coachKey; break;
                    case `match`: impactDelta -= 12; cocreateDelta -= 10; marginDelta += 3; coachKey = `coach_r3_match`; break;
                    case `ignore`: alignDelta -= 4; coachKey = `coach_r3_ignore`; break;
                }

                // Speed-to-trust: too slow and Veridian defaults to the consultancy (Common Error 6).
                // Mobilising fast is effort and prioritisation, not net-new euro — it buys alignment.
                if (d.speed >= 60) { alignDelta += 8; }
                else if (d.speed <= 25) {
                    alignDelta -= 6; ds.lostMandate = true; coachKey = `coach_r3_slow`;
                }

                // Segmentation across 3 bands / 4 languages. Differentiation costs budget but lands.
                if (d.segment === `banded`) { impactDelta += 8; spend += 20; }
                else { impactDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_uniform` : coachKey; }

                summaryKey = (d.scorecard === `balanced` && d.scope === `premium`) ? `sum_r3_good` : (d.scorecard === `cfo` ? `sum_r3_cfo` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit, measure & de-risk (Common Error 5: launch without measurement).
                switch (d.measure) {
                    case `checkpoints`: impactDelta += 16; alignDelta += 8; spend += 30; coachKey = `coach_r4_checkpoints`; break;
                    case `endcourse`: impactDelta -= 2; alignDelta -= 4; coachKey = `coach_r4_endcourse`; break;
                    case `none`: impactDelta -= 12; alignDelta -= 8; coachKey = `coach_r4_nomeasure`; break;
                }

                // Renewal logic — turning one cohort into a multi-year relationship.
                switch (d.renewal) {
                    case `multiyear`: alignDelta += 10; cocreateDelta += 6; coachKey = (d.measure === `checkpoints`) ? `coach_r4_multiyear` : coachKey; break;
                    case `referral`: alignDelta -= 2; break;
                    case `none`: alignDelta -= 6; coachKey = `coach_r4_norenewal`; break;
                }

                // De-risking delivery failure modes.
                switch (d.derisk) {
                    case `all`: impactDelta += 10; alignDelta += 6; spend += 25; break;
                    case `gaming`: impactDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_gaming` : coachKey; break;
                    case `senior`: impactDelta += 4; break;
                    case `slip`: impactDelta += 3; break;
                }

                // CEO-pitch conviction nudges impact and alignment.
                impactDelta += Math.round((d.pitch - 60) / 10);
                alignDelta += Math.round((d.pitch - 60) / 12);

                summaryKey = (d.measure === `checkpoints` && d.renewal === `multiyear`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Budget accounting. R2 fixes spend at the cap; R3/R4 add-ons can breach it.
            if (round === 2) {
                ds.budgetUsed = this.BUDGET_CAP;
            } else {
                ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            }
            // Hard cap: the CFO claws back overruns and remembers (Common Error 4: budget blow-out).
            // Penalise only the NEW overage committed this round, never re-penalise prior overage
            // (otherwise the same overrun is charged again every subsequent round).
            const overBy = ds.budgetUsed - this.BUDGET_CAP;
            if (typeof ds.prevOverBy !== `number`) ds.prevOverBy = 0;
            if (overBy > 0) {
                ds.overran = true;
                const newOverBy = Math.max(0, overBy - ds.prevOverBy);
                // Margin falls roughly one point per ~€18k of fresh overrun; alignment with the CFO suffers.
                marginDelta -= newOverBy / 18;
                alignDelta -= Math.min(14, Math.round(newOverBy / 8));
                if (round >= 3 && coachKey === `coach_default`) coachKey = `coach_overrun`;
            }
            ds.prevOverBy = Math.max(0, overBy);

            // Apply deltas with headroom-preserving clamps.
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.align = Math.max(0, Math.min(100, ds.align + alignDelta));
            ds.cocreate = Math.max(0, Math.min(100, ds.cocreate + cocreateDelta));
            ds.margin = Math.max(0, Math.min(45, ds.margin + marginDelta));

            // Losing the mandate (signed too late) caps alignment hard.
            if (ds.lostMandate) ds.align = Math.min(ds.align, 30);

            ds.impactHistory.push(Math.round(ds.impact));
            ds.alignHistory.push(Math.round(ds.align));
            ds.cocreateHistory.push(Math.round(ds.cocreate));

            // v1.1.0 fix: persist instructor-card composite every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                align: Math.round(ds.align),
                alignDelta: Math.round(alignDelta),
                cocreate: Math.round(ds.cocreate),
                cocreateDelta: Math.round(cocreateDelta),
                margin: Math.round(ds.margin),
                budgetUsed: ds.budgetUsed,
                overran: ds.overran,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`impactDisplay`, `domainState.impact`, (v) => Math.round(v));
            uiManager.bind(`alignDisplay`, `domainState.align`, (v) => Math.round(v));
            uiManager.bind(`cocreateDisplay`, `domainState.cocreate`, (v) => Math.round(v));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.cocreatesim-card-margin`);
                if (card) {
                    card.classList.toggle(`cocreatesim-margin-ok`, Number(v) >= this.MARGIN_HURDLE);
                    card.classList.toggle(`cocreatesim-margin-fail`, Number(v) < this.MARGIN_HURDLE);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.cocreatesim-budget-bar`);
                if (card) card.classList.toggle(`cocreatesim-budget-over`, Number(v) > this.BUDGET_CAP);
                return this._money(Number(v)) + ` / ` + this._money(this.BUDGET_CAP);
            });

            const self = this;

            // Candour slider readout.
            const cand = document.getElementById(`candourInput`);
            const candReadout = document.getElementById(`candourReadout`);
            if (cand && candReadout) {
                candReadout.textContent = cand.value;
                cand.addEventListener(`input`, function() { candReadout.textContent = cand.value; });
            }

            // Speed slider readout.
            const spd = document.getElementById(`speedInput`);
            const spdReadout = document.getElementById(`speedReadout`);
            if (spd && spdReadout) {
                spdReadout.textContent = spd.value;
                spd.addEventListener(`input`, function() { spdReadout.textContent = spd.value; });
            }

            // Budget allocation live total (€k).
            const allocIds = [`onjobInput`, `coachingInput`, `classInput`, `digitalInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = String(total);
                const bar = document.querySelector(`.cocreatesim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // Locale-aware EUR formatter. EN: "€840k" (symbol before).
        // ES: "840 k€" (symbol AFTER, comma decimal — here values are whole €k so no decimal needed).
        _money(valueK) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(valueK));
            if (lang === `es`) {
                return n + ` k€`;
            }
            return `€` + n + `k`;
        }

