        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.impactHistory.map((_, i) => (i === 0 ? this._tlabel(`chart_start`) : this._tlabel(`chart_round_prefix`) + i));
            return {
                cocreateChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.impactHistory },
                        { data: ds.alignHistory },
                        { data: ds.cocreateHistory }
                    ]
                }
            };
        }

        _tlabel(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        _composite(ds) {
            const impact = Math.round(ds.impact);
            const align = Math.round(ds.align);
            const cocreate = Math.round(ds.cocreate);
            const margin = Math.round(ds.margin);
            return Math.round(impact * 0.35 + align * 0.30 + cocreate * 0.25 + Math.min(100, margin * 2.5) * 0.10);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const impact = Math.round(ds.impact);
            const align = Math.round(ds.align);
            const cocreate = Math.round(ds.cocreate);
            const margin = Math.round(ds.margin);

            // The approval gate IS the 22% contribution-margin hurdle. An overrun already bites the
            // margin (CFO clawback, ~1pt per €18k); if the team still clears 22% the mandate is funded.
            // Only an overrun that actually drops margin below the hurdle loses to the budget.
            const hurdleCleared = margin >= this.MARGIN_HURDLE;
            const transformed = impact >= this.TARGET_IMPACT;
            const balanced = align >= 60;
            // Co-creation ceiling on a fully co-designed path is start 10 + codesign 30 + premium 8
            // + multiyear 6 = 54, so the "genuinely co-created" gate must sit at or below that.
            const cocreated = cocreate >= 50;
            const composite = this._composite(ds);

            let performanceKey = `grade_ordertaker`;
            if (transformed && balanced && cocreated && hurdleCleared && composite >= this.WIN_COMPOSITE) performanceKey = `grade_cocreated`;
            else if (transformed && balanced && hurdleCleared) performanceKey = `grade_credible`;
            else if (transformed && !cocreated) performanceKey = `grade_rented`;
            else if (!hurdleCleared) performanceKey = `grade_lostbudget`;
            else if (composite > 40) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = transformed && balanced && cocreated && hurdleCleared && composite >= this.WIN_COMPOSITE;

            const insights = [];
            if (transformed && balanced && cocreated && hurdleCleared) insights.push(window.mySimulation.t(`insight_won`));
            else if (transformed && !cocreated) insights.push(window.mySimulation.t(`insight_rented`));
            else if (!hurdleCleared) insights.push(window.mySimulation.t(`insight_budget`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (impact < 45) insights.push(window.mySimulation.t(`insight_lowimpact`));
            if (align < 45) insights.push(window.mySimulation.t(`insight_lowalign`));
            if (cocreate < 40) insights.push(window.mySimulation.t(`insight_lowcocreate`));
            if (ds.lostMandate) insights.push(window.mySimulation.t(`insight_lost`));
            if (transformed && balanced && cocreated && hurdleCleared) insights.push(window.mySimulation.t(`insight_renew`));

            return {
                impact: impact,
                align: align,
                cocreate: cocreate,
                margin: margin,
                transformed: transformed,
                hurdleCleared: hurdleCleared,
                cocreated: cocreated,
                lostMandate: !!ds.lostMandate,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="cocreate-cm-badge ` + (s.met ? `cocreate-cm-met` : `cocreate-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.hurdleCleared === false) badges.push(`<span class="cocreate-cm-badge cocreate-cm-fail">` + t(`cm_fail_budget`) + `</span>`);
            if (s.transformed === false) badges.push(`<span class="cocreate-cm-badge cocreate-cm-fail">` + t(`cm_fail_impact`) + `</span>`);
            if (s.lostMandate) badges.push(`<span class="cocreate-cm-badge cocreate-cm-fail">` + t(`cm_fail_lost`) + `</span>`);
            const kpi = (label, val) => `<div class="cocreate-cm-metric"><div class="cocreate-cm-metric-val">` + val + `</div><div class="cocreate-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_impact`), (s.impact != null ? s.impact : 0)) + kpi(t(`cm_align`), (s.align != null ? s.align : 0)) + kpi(t(`cm_cocreate`), (s.cocreate != null ? s.cocreate : 0)) + kpi(t(`cm_margin`), (s.margin != null ? s.margin : 0) + `%`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="cocreate-cm">`
                + `<div class="cocreate-cm-head"><div class="cocreate-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="cocreate-cm-scorewrap"><span class="cocreate-cm-score">` + score + `</span><span class="cocreate-cm-score-max">/100</span></div>`
                + `<div class="cocreate-cm-grade">` + grade + `</div>`
                + `<div class="cocreate-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="cocreate-cm-metrics">` + kpis + `</div>`
                + `<div class="cocreate-cm-insights"><div class="cocreate-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overran) return window.mySimulation.t(`hint_budget`);
            if (ds.cocreate < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cocreate`);
            if (ds.align < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_align`);
            if (state.currentPeriod >= 3 && ds.impact < 40) return window.mySimulation.t(`hint_impact`);
            if (ds.impact >= this.TARGET_IMPACT && ds.align >= 60 && ds.cocreate >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

